import time

from taf.sbts.oam.coam.admin import admin
from taf.sbts.oam.coam.admin.exceptions import AliasInUse

from taf.rfrl.csv4all.resources.utilities.decorators import decorate_cls_methods, admin_method_decorator
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


@decorate_cls_methods(admin_method_decorator)
class NodeAdmin(admin):
    def __init__(self, node_id=None, node_vm_host=None, node_vm_username: str = 'ute', node_vm_password: str = 'ute',
                 admin_logs_dir: str = "", node_ip: str = "192.168.255.129", alias=None,
                 webem_username: str = "Nemuadmin", webem_password: str = "nemuuser", setup_timeout: int = 120):
        super().__init__()
        self.node_id = node_id
        self.node_ip = node_ip
        self.node_vm_host = node_vm_host
        self.node_vm_username = node_vm_username
        self.node_vm_password = node_vm_password
        self.node_webem_username = webem_username
        self.node_webem_password = webem_password
        self.alias = f"CSV4ALL_{self.node_id}" if not alias else alias
        self.admin_connection = None
        self.admin_logs_dir = admin_logs_dir
        self.setup_timeout = setup_timeout
        self.setup_node_admin()

    def setup_node_admin(self):
        setup_attempt = 6
        for attempt in range(setup_attempt + 1):
            try:
                self.admin_connection = super().setup_admin(
                    alias=self.alias,
                    bts_host=self.node_ip,
                    username=self.node_webem_username,
                    password=self.node_webem_password,
                    remote_host=self.node_vm_host, remote_host_username=self.node_vm_username,
                    remote_host_password=self.node_vm_password, reduce_debug_prints=True,
                    update_interval=500, admin_api_log_dir=self.admin_logs_dir, timeout=self.setup_timeout)
                break
            except AliasInUse:
                if not self.alias:
                    test_logger(f"Alias CSV4ALL_{self.node_id} exists. "
                                f"Connection will be terminated and new one will be set up", "warn")
                self.teardown_admin(alias=self.alias)
            except Exception:
                if attempt == setup_attempt:
                    raise
                time.sleep(60)
                continue

    def collect_infomodel_log_from_current_session(self, target_file_name, timeout=60, connection=None,
                                                   leave_disconnect_logs=False, **kwargs):
        super().collect_infomodel_log_from_current_session(target_file_name=target_file_name, timeout=300,
                                                           connection=connection,
                                                           leave_disconnect_logs=leave_disconnect_logs)
